/* catalog.h - catalogue of custom levels (C11, no SDL).
 *
 * Model side. The catalogue is a user directory
 * (`$XDG_DATA_HOME/opendana/levels/`) holding one custom-level JSON per
 * entry plus a derived `catalog.json` index. The level files are the source of
 * truth: `catalog.json` is regenerated by scanning, so losing it loses nothing.
 *
 * All paths are built with '/' (accepted on every supported OS). The module is
 * pure C11 and tested without a window. */
#ifndef OD_EXT_CATALOG_H
#define OD_EXT_CATALOG_H

#include "opendana/common.h"
#include "opendana/ext/leveled.h"

#include <stddef.h>
#include <stdint.h>

#define OD_CATALOG_MAX_ENTRIES 1024

typedef struct {
    char id[OD_LED_ID_MAX];
    char name[OD_LED_NAME_MAX];
    char author[OD_LED_AUTHOR_MAX];
    int64_t created, modified;
    int theme_world;
    char file[256];      /* relative to the catalogue directory            */
    char thumb[256];     /* relative; empty when there is no thumbnail      */
} od_catalog_entry;

typedef enum {
    OD_CATALOG_SORT_NAME = 0,       /* ascending, then id (default)        */
    OD_CATALOG_SORT_MODIFIED = 1    /* most recent first, then name        */
} od_catalog_order;

/* Read the catalogue directory. Every `<id>.json` whose level loads is listed;
 * the result is sorted by name and `catalog.json` is rewritten. A missing
 * directory yields n=0 and OD_OK. If the directory holds more entries than
 * `max`, n=max and OD_ERR_RANGE is returned (nothing is deleted). */
od_status od_catalog_scan(const char *dir, od_catalog_entry *out, int max,
                            int *n);

/* Save `d` into the catalogue. When `d->id` is a valid free id it is reused
 * (saving over the edited entry), otherwise a unique id is derived from the
 * name. Writes `<id>.json` atomically and refreshes the index. */
od_status od_catalog_save(const char *dir, const od_led_doc *d,
                            char id_out[OD_LED_ID_MAX]);

/* Delete `<id>.json` and `<id>.png`. Idempotent; other entries are untouched. */
od_status od_catalog_delete(const char *dir, const char *id);

/* Copy an external level file into the catalogue under a fresh unique id. */
od_status od_catalog_import(const char *dir, const char *path,
                              char id_out[OD_LED_ID_MAX]);

/* Copy a catalogue entry out to `path`. */
od_status od_catalog_export(const char *dir, const char *id, const char *path);

/* ---- helpers used by the browser (C5.5) and the tests ------------------- */

void od_catalog_sort(od_catalog_entry *list, int n, od_catalog_order by);
int od_catalog_find(const od_catalog_entry *list, int n, const char *id);

/* Lowercase slug of `name` for an id (never empty; schema pattern safe). */
void od_catalog_make_id(const char *name, char *out, size_t cap);

#endif /* OD_EXT_CATALOG_H */
